		for (let i = 0; i < maxIt; i++) {
			await pi.events.get("tool_result")(
				{ type: "tool_result", toolName: "subagent", toolCallId: `b${i}`, input: { agent: "builder" }, content: [{ type: "text", text: "built" }], isError: false },
				c,
