			await pi.events.get("tool_result")(
				{ type: "tool_result", toolName: "subagent", toolCallId: `r${i}`, input: { agent: "commentator" }, content: [{ type: "text", text: "WORKFLOW_REVIEW_STATUS: blocking" }], isError: false },
