		expect(existsSync(join(dir, "loop-complete.md"))).toBe(false);
		expect(pi.entries.at(-1)?.data.phase).toBe("loop");
		expect(pi.notifies.some((n) => /max iterations/i.test(n.text) && n.level === "warning")).toBe(true);
